import app from "@/store/app";
import userStore from "@/store/userStore";
import { Message } from "@arco-design/web-react";
import axios, { AxiosRequestHeaders, Method } from "axios"
import _ from 'lodash';
import { ajaxUrl, aseDecrypt, aseEncrypt, generateRandomString, getEncryptedKey } from "./crypto";
import { returnToLogin } from ".";
import { getUploadCalculatePostSignature } from "./api";

const getHeaders = async (body, option: Option) => {
    const headers: AxiosRequestHeaders = {
        appid: app.appId,
        tenantid: app.tenantId,
    };
    if(userStore.token){
        headers.Authorization = `Bearer ${userStore.token}`
    }
    let cryptKey;
    /**
     * 参数加密
     */
     if(option.encrypt || option.decrypt){
        cryptKey = await generateRandomString(16);
        if(option.encrypt){
            body = _.cloneDeep(body);
            // 参数加密;
            if(option.encrypt === 'all'){
                body = { data: await aseEncrypt(cryptKey, body) };
            }else {
                for (const path of option.encrypt) {
                    const value = _.get(body, path);
                    if(value){	
                        _.set(body, path, await aseEncrypt(cryptKey,value));
                    }
                }
            }
            headers.encrypt = Array.isArray(option.encrypt)? option.encrypt.join(',') : option.encrypt;
        }
        // RSA 加密密钥
        headers.encryptkey = await getEncryptedKey(cryptKey)
    }

    return {
        cryptKey,
        headers,
        body,
    }
}
interface Option {
    // 禁止http 开头
    notHttp?: boolean;
    // 加密传输，要加密的字段
    encrypt?: 'all' | string[];
    // 是否需要解密，如果和后端约定数据加密返回，则需要传入当前字段
    decrypt?: boolean;
    // 是否需要缓存接口
    cache?: boolean;
    headers?: AxiosRequestHeaders;
    stream?: boolean; // 新增 stream 模式标识
    onProgress?: (chunk: string) => void; // 流数据回调
}
const ajaxCache = {};
const requestAxios = async <T = any>(
    method: Method = 'get',
    path: string,
    data: T,
    option: Option = {},
):Promise<any>  => {

    const { cryptKey, headers, body } = await getHeaders(data, option);
    // const url =  `${window.location.origin}/wizapi${path}`;
    let url = path.slice(0,4) == "http"? path :  ajaxUrl + path;
    if(option.notHttp){
        url = path;
    }

    const dataKey = `apiKey-${JSON.stringify(body)}`;
    // 如果缓存存在，则从缓存获取数据
    if(option.cache && ajaxCache[dataKey]) return ajaxCache[dataKey]; 
    const promiseAjax = new Promise((resolve, reject) => {

        axios({
            method,
            url,
            params: ['get', 'delete'].includes(method)? body : undefined,
            data: body,
            headers: Object.assign(headers, option.headers || {}),
            responseType: 'stream', // 流模式使用 arraybuffer
            onDownloadProgress: option.stream? (progressEvent) => {
                option?.onProgress(progressEvent.currentTarget.response);
            }: undefined,
        }).then(async (res) => {
            let data = res.data;
            if(typeof data == 'string' && (option.decrypt || option.encrypt)){
                // 加密获取，解密返回的参数
                data = await aseDecrypt(cryptKey, data);
            }
            if(typeof data === 'object' && 'code' in data){
                if(data.code === 0){
                    return resolve(data)
                }else {
                    // 飞正常请求，抛出错误
                    reject(data)
                }
            }else {
                resolve(data);
            }
        }).catch((err) => {
            console.log('ajax-error', err);
            const data = err.response && err.response.data
            if(typeof data === 'object'){
                if(data.code === 407){
                    // 登陆失效
                    // returnToLogin()
                    userStore.clearUserToken();
                }else if(data.message) {
                    Message.error(data.message)
                }
            }
            reject(err)
        })
    })
    ajaxCache[dataKey] = promiseAjax;
    return promiseAjax;
}
export default {
    post: <T = any>(url: string,data?:T, option?:Option) => {
        return requestAxios('post', url, data, option);
    },
    get: <T = any>(url: string,data?:T, option?:Option) => {
        return requestAxios('get', url, data, option);
    },
    del:  <T = any>(url: string,data?:T, option?:Option) => {
        return requestAxios('delete', url, data, option);
    },
    put: <T = any>(url: string,data?:T, option?:Option) => {
        return requestAxios('put', url, data, option);
    },
    request: async(method: Method = 'GET', path: string,data: any = {}, option:Option = {}) =>{
        let body: any = data;

        const { cryptKey, headers } = await getHeaders(body, option);
        const url = path.indexOf('http') !== -1? path : `/wizapi${path}`;
        return new Promise((resolve, reject) => {
            axios.request({
                method,
                url,
                data: body,
                headers: Object.assign(headers, option.headers || {}),
            }).then(async (res) => {
                let data = res.data;
                if(option.decrypt){
                    // 加密获取，解密返回的参数
                    data = await aseDecrypt(cryptKey, data);
                }
                resolve({ ...res, data });
            }).catch((err) => {
                const data = err.response && err.response.data
                if(typeof data === 'object' && data.msg){
                    Message.error(data.msg)
                }
                // 即使错误，也返回，用户api接口文档，统一ui显示
                resolve(err.response)
            })
        })
    },
}


// 将base64 转换为file类型
function base64URLtoFile(base64:string, filename:string = 'name.jpg') {
    var arr:any = base64.split(','), mime = arr[0].match(/:(.*?);/)[1],
    bstr = atob(arr[1]), n = bstr.length, u8arr = new Uint8Array(n);
    while(n--){
      u8arr[n] = bstr.charCodeAt(n);
   }
   return new File([u8arr], filename, {type:mime});
}


export function textToFile(text: string, filename:string = 'file.txt') {
    var mimeTypes = {
        'txt': 'text/plain',
        'html': 'text/html',
        'css': 'text/css',
        'js': 'text/javascript',
        'xml': 'text/xml',
        'json': 'application/json',
    };
    const fileExtension = filename.split('.').pop();

    var defaultMimeType = 'text/plain'; // 默认 MIME 类型
    // 根据文件扩展名获取 MIME 类型
    var mimeType = mimeTypes[fileExtension.toLowerCase()] || defaultMimeType;
    // 创建 Blob 对象
    var blob = new Blob([text], {type: mimeType});
    // 创建 File 对象
    var file = new File([blob], filename, {type: mimeType});

    return file;
}



