/**
 * 上传到oss （版本上传）
 */
const uploadOSS = (baseFile: string) => {
    let data: any = null;
    return async (
        file:any | string,
        fileName?: string
    ) => {
        if(typeof file === 'string'){
            file = textToFile(file, fileName);
        }
        if(!data){
            data = await getUploadCalculatePostSignature();
        }
        let filename =  file.name;
        const formData = new FormData();
        formData.append('name',filename);
        formData.append('policy', data.policy);
        formData.append('OSSAccessKeyId', data.ossAccessKeyId);
        formData.append('success_action_status', '200');
        formData.append('signature', data.signature);
        formData.append('key', `${data.dir}/${fileName}`);
        // file必须为最后一个表单域，除file以外的其他表单域无顺序要求。
        formData.append('file', file); 
        
        return fetch(data.host, { method: 'POST', body: formData },).then((res) => {
            return {
                url: `${res.url}${data.dir}/${fileName}`
            };
        });
    }
    
}

