import _ from 'lodash';

export function isArray(val): boolean {
  return Object.prototype.toString.call(val) === '[object Array]';
}
export function isObject(val): boolean {
  return Object.prototype.toString.call(val) === '[object Object]';
}
export function isString(val): boolean {
  return Object.prototype.toString.call(val) === '[object String]';
}

export function isFunction(val): boolean {
  return typeof val === 'function';
}
 
export function isPromise(val): boolean {
  return typeof val === 'object' && isFunction(val.then) && isFunction(val.catch) && isFunction(val.finally);
}

export function isRefSchema($ref, schema): boolean {
  const paths = $ref.split('/').slice(1);
  return _.has(schema, paths);
}

/**
 * 判断是否为function 类型，由string 类型转换
 */
export function isBuilderFun(str: any): boolean {
  return str.indexOf('function(') !== -1 || /\)\s*=>\s*\{/.test(str);
}

// 判断是否为构建起对象 `${ `app`.`name` }`
export function isBuilder(str: any): boolean {
  // 函数类型中可能也会存在`${ }`标示，但模版不应该进行解析
  return str && typeof str === 'string' && str.indexOf('${') !== -1;
}

// 判断当前是否为js内容
export function isJsxString(str: any): boolean {
  return str && typeof str === "string" && /^\$j{.+}$/.test(str);
}


// 判断当前是否为多语言内容
export function isTranslation(str: any): boolean {
  return str && typeof str === "string" && /^\$t{.+}$/.test(str);
}

// 返回多语言实际内容
export function getTranslation(str: any): string {
  return str.replace(/(\$t\{)|\s|\}/g, "");
}

/**
 * 判断字符串是否为大写字母开头
 */
export function isUpperCaseStart(str: string) {
  var firstChar = str.charAt(0);
  return firstChar === firstChar.toUpperCase();
}

 
export const isSSR = (function () {
  try {
    return !(typeof window !== 'undefined' && document !== undefined);
  } catch (e) {
    return true;
  }
})();
